// Stub of @hermes/plugin-sdk, shaped from the real exports read out of
// apps/desktop/src/sdk/index.ts. Only what zephyr imports.

export function atom(initial) {
  let value = initial
  const listeners = new Set()

  return {
    get: () => value,
    set: next => {
      value = next
      listeners.forEach(l => l(value))
    },
    subscribe: l => {
      listeners.add(l)
      return () => listeners.delete(l)
    }
  }
}

export const cn = (...args) => args.filter(a => typeof a === 'string' && a).join(' ')

export const useValue = store => store.get()

export const requestTheme = name => {
  globalThis.__themeCalls = globalThis.__themeCalls || []
  globalThis.__themeCalls.push(name)
  return true
}

export const setAccentOverride = color => {
  globalThis.__accentCalls = globalThis.__accentCalls || []
  globalThis.__accentCalls.push(color)
}

export const host = { state: { gateway: atom('open') } }

const component = name => props => ({ __stub: name, props })

